// --- Uniform cases: in_channels elements, all activation==act_value,
//     all weight==wgt_value (single output channel). Overflow boundary
//     (S8/S11 item 2), deep int64 exactness, SIMD-saturation-hazard cells. ---

struct UniformCase {
	const char* label;
	size_t in_channels;
	int8_t act_value;
	int8_t wgt_value;
	int64_t expected;      // the TRUE, unwrapped int64 sum -- always the kernel's contract
	int32_t wrapped_i32;   // what a (WRONG) naive int32 accumulator would produce
	bool overflows_i32;    // true iff expected does not fit int32 (documentation)
};

